        ReconcileRequest: {
            /**
             * Entity Id
             * @description The entity that changed: a canon entity of any kind, a character, or a lexicon term.
             */
            entity_id: string;
        };
        /**
         * Reconciliation
         * @description FR-OPS-08. Which written work depended on the entity, so a late decision does not force
         *     a re-read of the entire book.
         *
         *     `architecture.md` Operations: "Without this operation, every late decision forces a re-read
         *     of the entire book, which in practice means late decisions stop being made." The answer is
         *     deliberately a **superset** (AC 14): an extra scene costs one re-read, while a missed one
         *     is a contradiction nobody is told about, so every ambiguous edge is resolved towards
         *     inclusion.
         */
        Reconciliation: {
            /**
             * Defined In
             * @description The store files that define it, sorted. More than one means two records claim the id, which is itself worth knowing before deciding anything.
             */
            defined_in: string[];
            /**
             * Entity Id
             * @description The entity reconciled.
             */
            entity_id: string;
            /**
             * Scenes
             * @description Every scene that references the entity, sorted by scene id.
             */
            scenes: components["schemas"]["Dependent"][];
            /**
             * Turns
             * @description Every turn record whose selected list contains it, sorted by turn id.
             */
            turns: components["schemas"]["Dependent"][];
        };
        /**
         * Relationship
         * @description DR-08. What one character feels towards another, and how that has moved.
         *
         *     **Directed on purpose.** A can trust B while B despises A, and that asymmetry is not an
         *     inconvenience to be averaged away - it is dramatic material, and often the engine of a
         *     whole subplot. A symmetric edge would make the two indistinguishable. Two rows are
         *     written when the feeling runs both ways, and they are free to disagree.
         *
         *     **Failure mode: a single valence value instead of a dated series.** A scalar answers
         *     "do they get on?" and nothing else. It cannot answer "where were they at chapter
         *     nineteen?", so there is no queryable evolution, and relationships flatten into fixed
         *     dispositions - which is precisely what a novel is not about. The dated list is what
         *     makes a betrayal legible as a movement rather than an inconsistency.
         *
         *     **FR-OPS-01.** `dossier(character, at=T)` takes the latest entry in `valence` whose
         *     scene has `story_time <= T`, and nothing later appears. `shared_history` and `unspoken`
         *     are not dated, so they are read as standing context: `unspoken` in particular is what
         *     the pair never say to each other, which by construction has no scene to be dated from.
         */
